(function(){
  'use strict';

  const EWC_STANDARD_PLAYERS = {
    hak:'HAK', nickz:'NICKZ', nickz7:'NICKZ', trap:'TRAP', trap7:'TRAP', xtrap7:'TRAP',
    guaxa:'GUAXA', guaxa7:'GUAXA', bzp:'BZP', bzp10:'BZP', rigby:'Rigby245', rigby245:'Rigby245',
    general:'General!', generalx:'General!', gneralxx:'General!', raone7:'Raone7', yago:'Yago',
    mtsexy:'mtsexy.', bops:'Bops', giuh:'Giuh', but:'BuTziN', butzin:'BuTziN', mt7:'MT7', proxx7:'Proxx7'
  };


  const EWC_STANDARD_BY_TEAM = {
    loud: { hak:'HAK', nickz7:'NICKZ', trap:'TRAP', guaxa7:'GUAXA', bzp10:'BZP' },
    mibrlos: { rigby245:'Rigby245', general:'General!', raone7:'Raone7', yago:'Yago', mtsexy:'mtsexy.' },
    fluxow7m: { bops:'Bops', giuh:'Giuh', butzin:'BuTziN', mt7:'MT7', proxx7:'Proxx7' }
  };

  let summaryPromise = null;
  let summaryPayload = null;

  function normalize(value){
    return String(value || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]/gi, '')
      .toLowerCase();
  }

  function canonicalStandardName(name){
    return EWC_STANDARD_PLAYERS[normalize(name)] || String(name || '').trim();
  }

  function canonicalEWCStandard(name,team){
    const teamMap = EWC_STANDARD_BY_TEAM[normalize(team)];
    return teamMap ? (teamMap[normalize(name)] || '') : '';
  }

  function playerMatches(a,b){
    if (!a || !b) return false;
    if (typeof window.checkNameMatch === 'function') {
      try { if (window.checkNameMatch(a,b)) return true; } catch (_) {}
    }
    return normalize(a) === normalize(b);
  }

  function loadSummary(){
    if (summaryPayload) return Promise.resolve(summaryPayload);
    if (!summaryPromise) {
      summaryPromise = fetch('player-profile-summary-2026.json?v=20260718-player-profile-v2', { cache: 'default' })
        .then(function(response){
          if (!response.ok) throw new Error('Resumo de jogadores indisponível');
          return response.json();
        })
        .then(function(payload){
          summaryPayload = payload && Array.isArray(payload.players) ? payload : { players: [] };
          hydrateCurrentDatabase(summaryPayload);
          return summaryPayload;
        })
        .catch(function(error){
          console.error('[Perfil de jogador 2026]', error);
          return { players: [] };
        });
    }
    return summaryPromise;
  }

  function findSummary(payload,name){
    const wanted = canonicalStandardName(name);
    return (payload && Array.isArray(payload.players) ? payload.players : []).find(function(player){
      if (playerMatches(player.name, wanted)) return true;
      return (player.aliases || []).some(function(alias){ return playerMatches(alias, wanted) || playerMatches(alias, name); });
    }) || null;
  }

  function hydrateCurrentDatabase(payload){
    if (typeof db === 'undefined' || !db || !Array.isArray(db.players)) return;
    (payload.players || []).forEach(function(summary){
      const stats = summary.ffws && (summary.ffws.total || summary.ffws);
      if (!stats) return;
      let row = db.players.find(function(player){ return player && player.jogador && playerMatches(player.jogador, summary.name); });
      if (!row) {
        row = db.players.find(function(player){
          return player && player.jogador && (summary.aliases || []).some(function(alias){ return playerMatches(player.jogador, alias); });
        });
      }
      if (!row) return;
      row.abates = Number(stats.kills || 0);
      row.quedas = Number(stats.matches || 0);
      row.dano = Number(stats.damage || 0);
      row.assists = Number(stats.assists || 0);
      row.mvp = Number(stats.mvp || 0);
      row.recorde = Number(stats.record || 0);
      row.rankKills = Number(stats.rankKills || 0);
      row.rankDmg = Number(stats.rankDamage || 0);
      row.rankAssists = Number(stats.rankAssists || 0);
      if (stats.team) row.equipe = stats.team;
    });
  }

  function temporarilyBypassOptionalLoads(){
    const names = ['loadTeamAliases','loadNovosTorneios','loadMercado','loadPlayerAliases','loadLAFFData','cffLoadLAFF2025S1Finals'];
    const saved = [];
    names.forEach(function(name){
      if (typeof window[name] === 'function') {
        saved.push([name, window[name]]);
        window[name] = function(){ return Promise.resolve(null); };
      }
    });
    return function(){ saved.forEach(function(item){ window[item[0]] = item[1]; }); };
  }

  function setText(id,value){
    const element = document.getElementById(id);
    if (element) element.textContent = String(value);
  }

  function sumEditions(editions){
    return Object.values(editions || {}).reduce(function(total,edition){
      total.kills += Number(edition && (edition.k != null ? edition.k : edition.kills)) || 0;
      total.matches += Number(edition && (edition.q != null ? edition.q : (edition.quedas != null ? edition.quedas : edition.matches))) || 0;
      return total;
    }, { kills: 0, matches: 0 });
  }

  function removeEditionAliases(editions, aliases){
    const output = Object.assign({}, editions || {});
    const wanted = aliases.map(normalize);
    Object.keys(output).forEach(function(key){ if (wanted.includes(normalize(key))) delete output[key]; });
    return output;
  }

  function applyHistory(summary){
    const state = window.__cffPlayerHistoryScopeState;
    if (!state || !state.data) return false;

    let wb = removeEditionAliases(state.data.wb || {}, ['WB 2026 S1','FFWS BR 2026 S1','FFWS Brasil 2026 S1']);
    const laff = Object.assign({}, state.data.laff || {});
    const current = summary.ffws && (summary.ffws.total || summary.ffws);
    if (current && Number(current.matches || 0)) {
      wb['FFWS BR 2026 S1'] = {
        k: Number(current.kills || 0),
        q: Number(current.matches || 0),
        team: current.team || '',
        equipe: current.team || '',
        source: 'ffws-br',
        currentSeason: true
      };
    }

    const ewc = Object.assign({}, state.data.ewc || {});
    Object.keys(ewc).forEach(function(key){ if (normalize(key) === normalize('EWC 2026')) delete ewc[key]; });
    if (summary.ewc && Number(summary.ewc.matches || 0)) {
      ewc['EWC 2026'] = {
        k: Number(summary.ewc.kills || 0),
        q: Number(summary.ewc.matches || 0),
        team: summary.ewc.team || '',
        equipe: summary.ewc.team || '',
        source: 'ewc'
      };
    }

    const all = Object.assign({}, wb, laff, ewc);
    state.data.wb = wb;
    state.data.laff = laff;
    state.data.ewc = ewc;
    state.data.all = all;
    state.totals = Object.assign({}, state.totals || {}, {
      wb: sumEditions(wb), laff: sumEditions(laff), ewc: sumEditions(ewc), all: sumEditions(all)
    });

    if (typeof window.cffApplyPlayerHistoryScope === 'function') {
      try { window.cffApplyPlayerHistoryScope('all'); } catch (_) {}
    }
    if (typeof window.cffRenderPlayerEditionBreakdown === 'function') {
      try { window.cffRenderPlayerEditionBreakdown(all); } catch (_) {}
    }
    return true;
  }

  function applyCurrentSeason(summary){
    const current = summary.ffws && (summary.ffws.total || summary.ffws);
    if (!current || !Number(current.matches || 0)) return false;
    const title = document.getElementById('pp-current-title');
    const grid = document.getElementById('pp-current-grid');
    const matchesCard = document.getElementById('pp-quedas');
    if (title) {
      title.style.display = 'block';
      title.textContent = 'Desempenho Atual • FFWS BR 2026 S1';
    }
    if (grid) grid.style.display = 'grid';
    if (matchesCard && matchesCard.closest('div')) matchesCard.closest('div').style.display = 'block';

    const matches = Number(current.matches || 0);
    setText('pp-quedas', matches);
    setText('pp-tot-kills', Number(current.kills || 0));
    setText('pp-avg-kills', matches ? (Number(current.kills || 0) / matches).toFixed(2) : '0.00');
    setText('pp-rank-kills', '#' + Number(current.rankKills || 0));
    setText('pp-tot-dmg', Number(current.damage || 0).toLocaleString('pt-BR'));
    setText('pp-avg-dmg', matches ? Math.round(Number(current.damage || 0) / matches).toLocaleString('pt-BR') : '0');
    setText('pp-rank-dmg', '#' + Number(current.rankDamage || 0));
    setText('pp-tot-assists', Number(current.assists || 0));
    setText('pp-avg-assists', matches ? (Number(current.assists || 0) / matches).toFixed(2) : '0.00');
    setText('pp-rank-assists', '#' + Number(current.rankAssists || 0));
    setText('pp-record', Number(current.record || 0));
    setText('pp-tot-mvps', Number(current.mvp || 0));
    return true;
  }

  function applyProfileSummary(summary){
    if (!summary) return;
    applyCurrentSeason(summary);
    applyHistory(summary);
  }

  function scheduleProfileSummary(summary){
    [0,80,240,650,1300].forEach(function(delay){
      window.setTimeout(function(){
        const page = document.getElementById('player-profile');
        if (page && page.classList.contains('active')) applyProfileSummary(summary);
      }, delay);
    });
  }

  function patchStandardProfile(){
    const original = window.openPlayerProfile;
    if (typeof original !== 'function' || original.__cffUnified2026) return;

    async function unifiedOpenPlayerProfile(name){
      if (!name) return;
      const canonical = canonicalStandardName(name);
      const payload = await loadSummary();
      hydrateCurrentDatabase(payload);
      const summary = findSummary(payload, canonical) || findSummary(payload, name);
      const restore = temporarilyBypassOptionalLoads();
      let result;
      try {
        result = await original.call(window, summary ? summary.name : canonical);
      } finally {
        restore();
      }
      if (summary) scheduleProfileSummary(summary);
      return result;
    }

    unifiedOpenPlayerProfile.__cffUnified2026 = true;
    unifiedOpenPlayerProfile.__cffOriginal = original;
    window.openPlayerProfile = unifiedOpenPlayerProfile;
    try { openPlayerProfile = unifiedOpenPlayerProfile; } catch (_) {}
  }

  function patchEWCPlayerRouting(){
    const originalEWC = window.openEWCPlayerProfile;
    if (typeof originalEWC === 'function' && !originalEWC.__cffUnified2026) {
      const wrappedEWC = function(name,team){
        const canonical = canonicalEWCStandard(name,team);
        if (canonical && typeof window.openPlayerProfile === 'function') return window.openPlayerProfile(canonical);
        return originalEWC.call(window,name,team);
      };
      wrappedEWC.__cffUnified2026 = true;
      window.openEWCPlayerProfile = wrappedEWC;
    }

    const originalPool = window.navBuildPeopleSearchPool;
    if (typeof originalPool === 'function' && !originalPool.__cffUnified2026) {
      const wrappedPool = function(){
        const pool = originalPool.call(window) || [];
        const standard = pool.filter(function(item){ return item && item.type !== 'ewc-player'; });
        const result = [];
        pool.forEach(function(item){
          if (!item || item.type !== 'ewc-player') { result.push(item); return; }
          const parts = String(item.name || '').split('|||');
          const ewcName = parts[0] || item.title || '';
          const canonical = canonicalEWCStandard(ewcName, parts[1] || '');
          if (!canonical) { result.push(item); return; }
          const existing = standard.find(function(candidate){
            return candidate && candidate.type === 'player' && (playerMatches(candidate.name, canonical) || playerMatches(candidate.title, canonical));
          });
          if (existing) {
            existing.haystack = `${existing.haystack || ''} ${ewcName} ${parts[1] || ''} ewc 2026`.toLowerCase();
            existing.priority = Math.max(Number(existing.priority || 0), 9);
            return;
          }
          result.push(item);
        });
        return result;
      };
      wrappedPool.__cffUnified2026 = true;
      window.navBuildPeopleSearchPool = wrappedPool;
      try { navBuildPeopleSearchPool = wrappedPool; } catch (_) {}
    }

    const originalSelect = window.selectSearchResult || (typeof selectSearchResult === 'function' ? selectSearchResult : null);
    if (typeof originalSelect === 'function' && !originalSelect.__cffUnified2026) {
      const wrappedSelect = function(type,name){
        if (type === 'ewc-player') {
          if (typeof window.navCloseSearchUI === 'function') window.navCloseSearchUI();
          const parts = String(name || '').split('|||');
          const playerName = parts[0];
          const canonical = canonicalEWCStandard(playerName, parts[1] || '');
          if (canonical && typeof window.openPlayerProfile === 'function') return window.openPlayerProfile(canonical);
        }
        return originalSelect.call(window,type,name);
      };
      wrappedSelect.__cffUnified2026 = true;
      window.selectSearchResult = wrappedSelect;
      try { selectSearchResult = wrappedSelect; } catch (_) {}
    }
  }

  function initialize(){
    patchStandardProfile();
    patchEWCPlayerRouting();
    [1400,3200,6500].forEach(function(delay){ window.setTimeout(patchEWCPlayerRouting, delay); });
    (window.cffRunWhenIdle || function(callback){ return window.setTimeout(callback,1200); })(loadSummary,1200);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialize, { once:true });
  else initialize();
})();
